const fromForm = $('Paste a Review').isExecuted;
return $input.all().map((item) => {
  const j = item.json;
  if (fromForm) {
    const rating = Number(j['Star rating']);
    return { json: {
      platform: j.Platform || 'Other',
      reviewer: j['Reviewer name'] || null,
      rating: Number.isFinite(rating) && rating > 0 ? rating : null,
      review_text: j['Review text'] || '',
      source: 'form',
    } };
  }
  const from = JSON.stringify(j.from || j.From || '');
  const platform = /google/i.test(from) ? 'Google' : /yelp/i.test(from) ? 'Yelp'
    : /trustpilot/i.test(from) ? 'Trustpilot' : /facebook|meta/i.test(from) ? 'Facebook' : 'Other';
  const text = String(j.text || j.snippet || '').slice(0, 6000);
  const stars = text.match(/([1-5])\s*(?:\/\s*5|stars?|★)/i);
  return { json: {
    platform,
    reviewer: null,
    rating: stars ? Number(stars[1]) : null,
    review_text: text,
    source: 'email: ' + (j.subject || j.Subject || ''),
  } };
});

