function parseClaudeJson(text) {
  const raw = String(text || '').trim();
  const fenced = raw.match(/\x60\x60\x60(?:json)?\s*([\s\S]*?)\x60\x60\x60/);
  const candidate = fenced ? fenced[1] : raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
  try {
    return JSON.parse(candidate);
  } catch (e) {
    throw new Error('Claude did not return valid JSON. Raw reply: ' + raw.slice(0, 500));
  }
}
function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const settings = $('Config: Agent Settings').first().json;
const review = $('Normalize Review').item.json;
const ai = parseClaudeJson($json.text);

const words = String(settings.always_flag_words || '').split(',').map((w) => w.trim().toLowerCase()).filter(Boolean);
const hitWords = words.filter((w) => review.review_text.toLowerCase().includes(w));
const lowStars = review.rating !== null && review.rating <= Number(settings.flag_at_or_below_stars);
const needsHuman = Boolean(ai.needs_human) || ai.sentiment === 'negative' || lowStars || hitWords.length > 0;

const reasons = [];
if (lowStars) reasons.push(review.rating + ' stars');
if (hitWords.length) reasons.push('mentions: ' + hitWords.join(', '));
if (ai.reason) reasons.push(ai.reason);

const tag = needsHuman ? '[NEEDS YOU]' : '[READY TO POST]';
const stars = review.rating ? review.rating + '-star ' : '';
const html = (needsHuman
    ? '<p><b>This review needs you.</b> Read it and decide how to respond before posting anything.</p>'
    : '<p>This reply looks safe to post. Give it a quick read first.</p>') +
  '<p><b>Why:</b> ' + esc(reasons.join(' / ') || 'n/a') + '</p>' +
  '<h3>Review (' + esc(review.platform) + ', ' + esc(review.rating ?? 'no') + ' stars)</h3>' +
  '<blockquote>' + esc(review.review_text).replace(/\n/g, '<br>') + '</blockquote>' +
  '<h3>Suggested reply</h3><p>' + esc(ai.reply).replace(/\n/g, '<br>') + '</p>' +
  '<p><i>Source: ' + esc(review.source) + '</i></p>';

return { json: {
  subject: tag + ' ' + stars + review.platform + ' review from ' + (review.reviewer || 'a customer'),
  html,
  needs_human: needsHuman,
} };
